5	import Link from "next/link";
6	import { useQuery } from "@tanstack/react-query";
7	import { supabase } from "@/integrations/supabase/client";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { Badge } from "@/components/ui/badge";
10	import { Button } from "@/components/ui/button";
11	import { Input } from "@/components/ui/input";
12	import { Card, CardContent } from "@/components/ui/card";
13	import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
14	import { Briefcase, Layers, Search, Globe, Linkedin, Twitter, Instagram, Facebook, Bell, Quote } from "lucide-react";
15	import JobListingCard from "@/components/career/JobListingCard";
