73	
74	// ---------------------------------------------------------------------------
75	// Helpers
76	// ---------------------------------------------------------------------------
77	
78	function sanitizeCSS(css: string): string {
79	  if (!css) return "";
80	  return css
81	    .replace(/@import\b/gi, "/* blocked @import */")
82	    .replace(/javascript\s*:/gi, "/* blocked */")
83	    .replace(/expression\s*\(/gi, "/* blocked */")
84	    .replace(/behavior\s*:/gi, "/* blocked */")
85	    .replace(/url\s*\(\s*["']?\s*(?!https?:\/\/)/gi, "url(/* blocked */")
86	    .replace(/<\/?script/gi, "/* blocked */");
87	}
88	
89	const iconFallbacks: Record<string, string> = {
90	  Heart: "❤️", Star: "⭐", Zap: "⚡", Globe: "🌍", Shield: "🛡️",
91	  Award: "🏆", Coffee: "☕", Users: "👥", TrendingUp: "📈", Home: "🏠",
92	  Smile: "😊", Clock: "⏰", DollarSign: "💰", Gift: "🎁", Briefcase: "💼",
93	  Laptop: "💻", Plane: "✈️", BookOpen: "📚", Music: "🎵", Camera: "📷",
94	};
95	
96	function BenefitIcon({ name }: { name: string }) {
97	  const emoji = iconFallbacks[name] ?? "✦";
98	  return (
99	    <span className="text-2xl leading-none" role="img" aria-label={name}>
100	      {emoji}

1	"use client";
2	
3	import React, { useState, useEffect } from "react";
4	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
5	import { supabase } from "@/integrations/supabase/client";
6	import { Button } from "@/components/ui/button";
7	import { Badge } from "@/components/ui/badge";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { Switch } from "@/components/ui/switch";
10	import { Label } from "@/components/ui/label";
11	import {
12	  Select,
13	  SelectContent,
14	  SelectItem,
15	  SelectTrigger,
16	  SelectValue,
17	} from "@/components/ui/select";
18	import {
19	  Table,
20	  TableBody,
21	  TableCell,
22	  TableHead,
23	  TableHeader,
24	  TableRow,
25	} from "@/components/ui/table";
26	import { toast } from "sonner";
27	import {
28	  Download,
29	  ExternalLink,
30	  Users,
31	  Loader2,
32	  FileText,
33	  ChevronDown,
34	  ChevronRight,
35	  Ban,
36	} from "lucide-react";
37	
38	type ApplicationStatus = "pending" | "reviewed" | "shortlisted" | "rejected";
39	
40	interface Application {
41	  id: string;
42	  job_id: string;
43	  name: string;
44	  email: string;
45	  phone: string | null;
46	  linkedin_url: string | null;
47	  resume_path: string | null;
48	  resume_filename: string | null;
49	  status: ApplicationStatus;
50	  created_at: string;
51	  custom_fields: Record<string, unknown> | null;
52	  auto_disqualified: boolean | null;
53	  disqualify_reason: string | null;
54	}
55	
56	const STATUS_LABELS: Record<ApplicationStatus, string> = {
57	  pending: "Pending",
58	  reviewed: "Reviewed",
59	  shortlisted: "Shortlisted",
60	  rejected: "Rejected",
61	};
62	
63	const STATUS_COLORS: Record<ApplicationStatus, string> = {
64	  pending: "bg-muted text-muted-foreground",
65	  reviewed: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
66	  shortlisted:
67	    "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400",
68	  rejected:
69	    "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
70	};
71	
72	interface ApplicationsTabProps {
73	  jobId: string;
74	}
75	
76	export default function ApplicationsTab({ jobId }: ApplicationsTabProps) {
77	  const queryClient = useQueryClient();
78	  const [updatingId, setUpdatingId] = useState<string | null>(null);
79	  const [hideDisqualified, setHideDisqualified] = useState(false);
80	  const [expandedCustomFields, setExpandedCustomFields] = useState<Set<string>>(new Set());
81	
82	  // Fetch form field definitions to map field IDs to human-readable labels
83	  const { data: formFields } = useQuery<Record<string, string>>({
84	    queryKey: ["form-field-labels", jobId],
85	    queryFn: async () => {
86	      const { data } = await (supabase as any)
87	        .from("job_form_fields")
88	        .select("id, label")
89	        .eq("job_id", jobId);
90	      if (!data) return {};
91	      return Object.fromEntries((data as { id: string; label: string }[]).map((f) => [f.id, f.label]));
92	    },
93	    enabled: !!jobId,
94	    staleTime: 5 * 60 * 1000,
95	  });
96	
97	  const {
98	    data: applications,
99	    isLoading,
100	    error,
101	  } = useQuery<Application[]>({
102	    queryKey: ["applications", jobId],
103	    queryFn: async () => {
104	      const { data, error } = await (supabase as any)
105	        .from("applications")
106	        .select(
107	          "id, job_id, name, email, phone, linkedin_url, resume_path, resume_filename, status, created_at, custom_fields, auto_disqualified, disqualify_reason"
108	        )
109	        .eq("job_id", jobId)
110	        .order("created_at", { ascending: false });
111	      if (error) throw new Error(error.message);
112	      return (data ?? []) as Application[];
113	    },
114	    enabled: !!jobId,
115	    staleTime: 30_000,
116	  });
117	
118	  // Realtime subscription — auto-refresh when new applications arrive
119	  useEffect(() => {
120	    const channel = supabase
121	      .channel(`applications-${jobId}`)
122	      .on(
123	        "postgres_changes",
124	        {
125	          event: "INSERT",
126	          schema: "public",
127	          table: "applications",
128	          filter: `job_id=eq.${jobId}`,
129	        },
130	        () => {
131	          queryClient.invalidateQueries({ queryKey: ["applications", jobId] });
132	        }
133	      )
134	      .subscribe();
135	
136	    return () => {
137	      supabase.removeChannel(channel);
138	    };
139	  }, [jobId, queryClient]);
140	
141	  const updateStatus = useMutation({
142	    mutationFn: async ({
143	      applicationId,
144	      newStatus,
145	    }: {
146	      applicationId: string;
147	      newStatus: ApplicationStatus;
148	    }) => {
149	      const { error } = await supabase
150	        .from("applications")
151	        .update({ status: newStatus })
152	        .eq("id", applicationId);
153	      if (error) throw new Error(error.message);
154	    },
155	    onMutate: ({ applicationId }) => setUpdatingId(applicationId),
156	    onSuccess: (_, { applicationId, newStatus }) => {
157	      queryClient.setQueryData<Application[]>(
158	        ["applications", jobId],
159	        (prev) =>
160	          (prev ?? []).map((a) =>
161	            a.id === applicationId ? { ...a, status: newStatus } : a
162	          )
163	      );
164	      toast.success(`Application marked as ${STATUS_LABELS[newStatus]}`);
165	    },
166	    onError: (err: Error) => toast.error(err.message || "Failed to update status"),
167	    onSettled: () => setUpdatingId(null),
168	  });
169	
170	  const downloadResume = async (resumePath: string, filename: string) => {
171	    const { data, error } = await supabase.storage
172	      .from("resumes")
173	      .download(resumePath);
174	    if (error || !data) {
175	      toast.error("Failed to download resume");
176	      return;
177	    }
178	    const url = URL.createObjectURL(data);
179	    const a = document.createElement("a");
180	    a.href = url;
181	    a.download = filename;
182	    a.click();
183	    URL.revokeObjectURL(url);
184	  };
185	
186	  const formatDate = (iso: string) =>
187	    new Date(iso).toLocaleDateString("en-US", {
188	      month: "short",
189	      day: "numeric",
190	      year: "numeric",
191	    });
192	
193	  if (isLoading) {
194	    return (
195	      <div className="space-y-3">
196	        {[0, 1, 2, 3].map((i) => (
197	          <Skeleton key={i} className="h-12 w-full rounded-md" />
198	        ))}
199	      </div>
200	    );
201	  }
202	
203	  if (error) {
204	    return (
205	      <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-4 text-sm text-destructive">
206	        Failed to load applications. Please refresh the page.
207	      </div>
208	    );
209	  }
210	
211	  if (!applications || applications.length === 0) {
212	    return (
213	      <div className="flex flex-col items-center justify-center py-16 space-y-4">
214	        <div className="rounded-xl bg-muted/50 p-4">
215	          <Users className="h-8 w-8 text-muted-foreground/50" />
216	        </div>
217	        <div className="text-center space-y-1">
218	          <h3 className="text-sm font-medium">No applications yet</h3>
219	          <p className="text-sm text-muted-foreground max-w-xs">
220	            Share your apply link to start receiving applications from candidates.
221	          </p>
222	        </div>
223	      </div>
224	    );
225	  }
226	
227	  const visibleApplications = hideDisqualified
228	    ? (applications ?? []).filter((a) => !a.auto_disqualified)
229	    : (applications ?? []);
230	
231	  const disqualifiedCount = (applications ?? []).filter((a) => a.auto_disqualified).length;
232	
233	  return (
234	    <div className="space-y-3">
235	      <div className="flex items-center justify-between flex-wrap gap-2">
236	        <p className="text-sm text-muted-foreground">
237	          {applications.length} application{applications.length !== 1 ? "s" : ""}
238	          {disqualifiedCount > 0 && (
239	            <span className="ml-1.5 text-xs text-red-600 dark:text-red-400">
240	              ({disqualifiedCount} auto-disqualified)
241	            </span>
242	          )}
243	        </p>
244	        <div className="flex items-center gap-3 flex-wrap">
245	          {disqualifiedCount > 0 && (
246	            <div className="flex items-center gap-1.5">
247	              <Switch
248	                id="hide-disqualified"
249	                checked={hideDisqualified}
250	                onCheckedChange={setHideDisqualified}
251	                className="scale-75"
252	              />
253	              <Label htmlFor="hide-disqualified" className="text-xs cursor-pointer text-muted-foreground">
254	                Hide disqualified
255	              </Label>
256	            </div>
257	          )}
258	          <div className="flex items-center gap-2 text-xs text-muted-foreground">
259	            {(["pending", "reviewed", "shortlisted", "rejected"] as const).map((s) => {
260	              const count = applications.filter((a) => a.status === s).length;
261	              if (count === 0) return null;
262	              return (
263	                <span
264	                  key={s}
265	                  className={`px-2 py-0.5 rounded-full text-[11px] font-medium ${STATUS_COLORS[s]}`}
266	                >
267	                  {count} {STATUS_LABELS[s]}
268	                </span>
269	              );
270	            })}
271	          </div>
272	        </div>
273	      </div>
274	
275	      <div className="rounded-md border border-border overflow-hidden">
276	        <div className="overflow-x-auto">
277	          <Table>
278	            <TableHeader className="bg-muted/40">
279	              <TableRow>
280	                <TableHead className="pl-4">Candidate</TableHead>
281	                <TableHead>Contact</TableHead>
282	                <TableHead>Resume</TableHead>
283	                <TableHead className="w-36">Status</TableHead>
284	                <TableHead className="w-28 text-right pr-4">Submitted</TableHead>
285	              </TableRow>
286	            </TableHeader>
287	            <TableBody>
288	              {visibleApplications.map((app) => {
289	                const hasCustomFields =
290	                  app.custom_fields &&
291	                  Object.keys(app.custom_fields).length > 0;
292	                const isExpanded = expandedCustomFields.has(app.id);
293	
294	                return (
295	                  <React.Fragment key={app.id}>
296	                    <TableRow
297	                      className={`align-middle ${app.auto_disqualified ? "opacity-60" : ""}`}
298	                    >
299	                      {/* Name + LinkedIn + disqualified badge */}
300	                      <TableCell className="pl-4 py-3">
301	                        <div className="space-y-0.5">
302	                          <div className="flex items-center gap-1.5 flex-wrap">
303	                            <p className="text-sm font-medium leading-tight">
304	                              {app.name}
305	                            </p>
306	                            {app.auto_disqualified && (
307	                              <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400">
308	                                <Ban className="h-2.5 w-2.5" />
309	                                Disqualified
310	                              </span>
311	                            )}
312	                          </div>
313	                          {app.auto_disqualified && app.disqualify_reason && (
314	                            <p className="text-[11px] text-red-600 dark:text-red-400">
315	                              {app.disqualify_reason}
316	                            </p>
317	                          )}
318	                          {app.linkedin_url && (
319	                            <a
320	                              href={app.linkedin_url}
321	                              target="_blank"
322	                              rel="noopener noreferrer"
323	                              className="inline-flex items-center gap-1 text-xs text-primary hover:text-primary/80 transition-colors"
324	                            >
325	                              <ExternalLink className="h-3 w-3" />
326	                              LinkedIn
327	                            </a>
328	                          )}
329	                        </div>
330	                      </TableCell>
331	
332	                      {/* Email + Phone */}
333	                      <TableCell className="py-3">
334	                        <div className="space-y-0.5">
335	                          <p className="text-xs text-muted-foreground truncate max-w-[180px]">
336	                            {app.email}
337	                          </p>
338	                          {app.phone && (
339	                            <p className="text-xs text-muted-foreground">
340	                              {app.phone}
341	                            </p>
342	                          )}
343	                        </div>
344	                      </TableCell>
345	
346	                      {/* Resume download */}
347	                      <TableCell className="py-3">
348	                        {app.resume_path && app.resume_filename ? (
349	                          <Button
350	                            variant="ghost"
351	                            size="sm"
352	                            className="h-7 gap-1.5 text-xs px-2"
353	                            onClick={() =>
354	                              downloadResume(app.resume_path!, app.resume_filename!)
355	                            }
356	                            title={`Download ${app.resume_filename}`}
357	                          >
358	                            <Download className="h-3.5 w-3.5" />
359	                            {app.resume_filename.length > 20
360	                              ? app.resume_filename.slice(0, 18) + "…"
361	                              : app.resume_filename}
362	                          </Button>
363	                        ) : (
364	                          <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
365	                            <FileText className="h-3.5 w-3.5" />
366	                            No file
367	                          </span>
368	                        )}
369	                      </TableCell>
370	
371	                      {/* Status select */}
372	                      <TableCell className="py-3">
373	                        <div className="relative">
374	                          {updatingId === app.id && (
375	                            <Loader2 className="absolute -left-5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 animate-spin text-primary" />
376	                          )}
377	                          <Select
378	                            value={app.status}
379	                            onValueChange={(val) =>
380	                              updateStatus.mutate({
381	                                applicationId: app.id,
382	                                newStatus: val as ApplicationStatus,
383	                              })
384	                            }
385	                            disabled={updatingId === app.id}
386	                          >
387	                            <SelectTrigger className="h-7 text-xs w-32">
388	                              <SelectValue>
389	                                <span
390	                                  className={`px-1.5 py-0.5 rounded text-[11px] font-medium ${STATUS_COLORS[app.status]}`}
391	                                >
392	                                  {STATUS_LABELS[app.status]}
393	                                </span>
394	                              </SelectValue>
395	                            </SelectTrigger>
396	                            <SelectContent>
397	                              {(
398	                                ["pending", "reviewed", "shortlisted", "rejected"] as const
399	                              ).map((s) => (
400	                                <SelectItem key={s} value={s} className="text-xs">
401	                                  <span
402	                                    className={`px-1.5 py-0.5 rounded text-[11px] font-medium ${STATUS_COLORS[s]}`}
403	                                  >
404	                                    {STATUS_LABELS[s]}
405	                                  </span>
406	                                </SelectItem>
407	                              ))}
408	                            </SelectContent>
409	                          </Select>
410	                        </div>
411	                      </TableCell>
412	
413	                      {/* Date + expand custom fields */}
414	                      <TableCell className="text-right text-xs text-muted-foreground pr-4 py-3">
415	                        <div className="flex items-center justify-end gap-1.5">
416	                          {hasCustomFields && (
417	                            <button
418	                              onClick={() =>
419	                                setExpandedCustomFields((prev) => {
420	                                  const next = new Set(prev);
421	                                  if (next.has(app.id)) next.delete(app.id);
422	                                  else next.add(app.id);
423	                                  return next;
424	                                })
425	                              }
426	                              className="text-muted-foreground hover:text-foreground transition-colors"
427	                              title="Toggle custom answers"
428	                            >
429	                              {isExpanded ? (
430	                                <ChevronDown className="h-3.5 w-3.5" />
431	                              ) : (
432	                                <ChevronRight className="h-3.5 w-3.5" />
433	                              )}
434	                            </button>
435	                          )}
436	                          {formatDate(app.created_at)}
437	                        </div>
438	                      </TableCell>
439	                    </TableRow>
440	
441	                    {/* Expanded custom fields row */}
442	                    {isExpanded && hasCustomFields && (
443	                      <TableRow key={`${app.id}-custom`} className="bg-muted/30">
444	                        <TableCell colSpan={5} className="pl-8 pr-4 py-3">
445	                          <div className="space-y-1.5">
446	                            <p className="text-[11px] font-medium text-muted-foreground uppercase tracking-wider mb-2">
447	                              Custom Answers
448	                            </p>
449	                            {Object.entries(app.custom_fields ?? {}).map(
450	                              ([fieldId, val]) => (
451	                                <div key={fieldId} className="flex gap-2 text-xs">
452	                                  <span className="text-muted-foreground shrink-0 min-w-[120px] truncate">
453	                                    {formFields?.[fieldId] ?? fieldId}:
454	                                  </span>
455	                                  <span className="text-foreground break-words">
456	                                    {Array.isArray(val)
457	                                      ? val.join(", ")
458	                                      : typeof val === "boolean"
459	                                      ? val
460	                                        ? "Yes"
461	                                        : "No"
462	                                      : String(val ?? "")}
463	                                  </span>
464	                                </div>
465	                              )
466	                            )}
467	                          </div>
468	                        </TableCell>
469	                      </TableRow>
470	                    )}
471	                  </React.Fragment>
472	                );
473	              })}
474	            </TableBody>
475	          </Table>
476	        </div>
477	      </div>
478	    </div>
479	  );
480	}
