1	"use client";
2	
3	import { useState, useCallback, useRef, useEffect, useMemo } from "react";
4	import { useQuery, useQueryClient } from "@tanstack/react-query";
5	import { useAuth } from "@/hooks/useAuth";
6	import { usePlatformConfig } from "@/hooks/usePlatformConfig";
7	import { validateRanking } from "@/lib/validateRanking";
8	import { findDuplicateResumeIds } from "@/lib/deduplicateCandidates";
9	import { supabase } from "@/integrations/supabase/client";
10	import { Button } from "@/components/ui/button";
11	import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
12	import { Textarea } from "@/components/ui/textarea";
13	import { Checkbox } from "@/components/ui/checkbox";
14	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
15	import { Badge } from "@/components/ui/badge";
16	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
17	import { Progress } from "@/components/ui/progress";
18	import { Skeleton } from "@/components/ui/skeleton";
19	import {
20	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
21	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
22	} from "@/components/ui/alert-dialog";
23	import { toast } from "sonner";
24	import {
25	  Upload, Copy, Loader2, FileText,
26	  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2, FileSpreadsheet,
27	  ListChecks, ArrowRight, Users, Mail,
28	  Archive, ArchiveRestore, FolderOpen, Pencil, Wallet, ScanLine, Zap,
29	  ChevronLeft, Link2, ClipboardCheck, MapPin, ChevronDown, Share2,
30	  LayoutGrid, Sparkles,
31	} from "lucide-react";
