42	/**
43	 * Verify webhook signature using HMAC-SHA256.
44	 * Supports X-Webhook-Signature header or a shared secret via query param.
45	 */
46	async function verifyWebhookSignature(req: Request, body: ArrayBuffer): Promise<boolean> {
47	  const secret = Deno.env.get("EMAIL_INGEST_WEBHOOK_SECRET");
48	  if (!secret) {
49	    // If no secret is configured, reject all requests for safety.
50	    // Operators must set EMAIL_INGEST_WEBHOOK_SECRET to enable email ingestion.
51	    console.error("EMAIL_INGEST_WEBHOOK_SECRET not configured — rejecting request");
52	    return false;
53	  }
54	
55	  // Check signature header
56	  const signature = req.headers.get("x-webhook-signature");
57	
58	  if (!signature) {
59	    // Also allow secret as a query parameter (for simpler webhook providers)
60	    const url = new URL(req.url);
61	    const querySecret = url.searchParams.get("secret");
62	    return querySecret === secret;
63	  }
64	
65	  // Verify HMAC-SHA256 signature
66	  try {
67	    const key = await crypto.subtle.importKey(
68	      "raw",
69	      new TextEncoder().encode(secret),
70	      { name: "HMAC", hash: "SHA-256" },
71	      false,
72	      ["verify"]
73	    );
74	
75	    const signatureBytes = Uint8Array.from(
76	      atob(signature),
77	      (c: string) => c.charCodeAt(0)
78	    );
79	
80	    return await crypto.subtle.verify("HMAC", key, signatureBytes, body);
81	  } catch (e) {
82	    console.error("Signature verification failed:", e);
83	    return false;
84	  }
85	}
