145	function extractTotalYears(rolesWithDates: any[]): number {
146	  if (!Array.isArray(rolesWithDates) || rolesWithDates.length === 0) return 0;
147	
148	  const intervals: { start: number; end: number }[] = [];
149	  const currentYear = new Date().getFullYear();
150	  const currentMonth = new Date().getMonth() + 1;
151	
152	  for (const role of rolesWithDates) {
153	    const startRaw = role.start || role.start_date || role.from || "";
154	    const endRaw = role.end || role.end_date || role.to || "";
155	
156	    const startDate = parseDate(String(startRaw), currentYear, currentMonth);
157	    let endDate = parseDate(String(endRaw), currentYear, currentMonth);
158	
159	    // Handle "present", "current", "ongoing" etc.
160	    const endLower = String(endRaw).toLowerCase().trim();
161	    if (!endRaw || endLower === "present" || endLower === "current" || endLower === "ongoing" || endLower === "now" || endLower === "till date" || endLower === "till now") {
162	      endDate = currentYear + (currentMonth - 1) / 12;
163	    }
164	
165	    if (startDate > 0 && endDate > 0 && endDate >= startDate) {
166	      intervals.push({ start: startDate, end: endDate });
167	    }
168	  }
169	
170	  if (intervals.length === 0) return 0;
171	
172	  // Merge overlapping intervals to avoid double-counting
173	  intervals.sort((a, b) => a.start - b.start);
174	  const merged: { start: number; end: number }[] = [intervals[0]];
175	  for (let i = 1; i < intervals.length; i++) {
176	    const last = merged[merged.length - 1];
177	    if (intervals[i].start <= last.end) {
178	      last.end = Math.max(last.end, intervals[i].end);
179	    } else {
180	      merged.push(intervals[i]);
181	    }
182	  }
183	
184	  let totalYears = 0;
185	  for (const iv of merged) {
186	    totalYears += iv.end - iv.start;
187	  }
188	  return Math.round(totalYears * 10) / 10; // 1 decimal
189	}
